-- =============================================================================
-- Subtrack: demo data ("Settings > Reset demo data")
--
-- seed_demo_data() replaces the caller's data with the sample account from
-- shared/src/seed.ts, generated relative to "today" so renewals and trials
-- are always upcoming. The definitions below are generated from DEMO_DEFS
-- (node shared/scripts/to-sql.ts demo); build() is ported to SQL further down.
-- The profile (rates, is_student, ...) is left as it is.
-- =============================================================================

-- Generated by `node shared/scripts/to-sql.ts demo` from DEMO_DEFS in shared/src/seed.ts.
-- Names, prices and cards are fictional sample values.
create or replace function private.demo_subscription_defs()
returns jsonb
language sql
immutable
set search_path = ''
as $defs$
  select $json$
[
  {"id":"s-chatgpt","serviceId":"chatgpt","name":"ChatGPT","plan":"Plus","category":"software","currency":"USD","cycle":"monthly","next":1,"since":15,"prices":[[15,20]],"usage":"daily","reminderDays":1,"paymentMethod":"Revolut 0921"},
