-- Port of build() in shared/src/seed.ts: demo definitions -> `Subscription` JSON.
create function private.demo_subscriptions(p_today date)
returns jsonb
language sql
stable
set search_path = ''
as $$
  select coalesce(jsonb_agg(t.sub order by t.ord), '[]'::jsonb)
  from (
    select e.ord,
           jsonb_strip_nulls(jsonb_build_object(
             'serviceId',     e.d ->> 'serviceId',
             'name',          e.d ->> 'name',
             'plan',          e.d ->> 'plan',
             'category',      e.d ->> 'category',
             'currency',      e.d ->> 'currency',
             'schedule',      jsonb_build_array(jsonb_build_object('from', b.first_charge, 'start', b.first_charge, 'cycle', e.d ->> 'cycle')),
             'priceHistory',  (select jsonb_agg(
                                        jsonb_build_object(
                                          'date', public.add_cycle(a.next_charge, (e.d ->> 'cycle')::public.billing_cycle, -(p.v ->> 0)::integer),
                                          'amount', (p.v ->> 1)::numeric)
                                        order by p.i)
                                 from jsonb_array_elements(e.d -> 'prices') with ordinality as p(v, i)),
             'status',        coalesce(e.d ->> 'status', 'active'),
             'trialEndsAt',   case when e.d ->> 'status' = 'trial' then a.next_charge end,
             'cancelledAt',   p_today - (e.d ->> 'cancelledDaysAgo')::integer,
             'pauses',        case when e.d ? 'pausedDaysAgo'
                                then jsonb_build_array(jsonb_build_object('from', p_today - (e.d ->> 'pausedDaysAgo')::integer))
                              end,
             'reminderDays',  coalesce((e.d ->> 'reminderDays')::integer, 3),
             'usage',         e.d ->> 'usage',
             'paymentMethod', e.d ->> 'paymentMethod',
             'notes',         e.d ->> 'notes',
             'createdAt',     case when e.d ? 'createdDaysAgo'
                                then p_today - (e.d ->> 'createdDaysAgo')::integer
                                else b.first_charge
                              end
           )) as sub
    from jsonb_array_elements(private.demo_subscription_defs()) with ordinality as e(d, ord)
    cross join lateral (select p_today + (e.d ->> 'next')::integer as next_charge) a
    cross join lateral (
      select public.add_cycle(a.next_charge, (e.d ->> 'cycle')::public.billing_cycle, -(e.d ->> 'since')::integer) as first_charge
    ) b
  ) t
$$;

-- Writes the demo subscriptions for a user. Also usable from the SQL editor
-- (as postgres) to fill a test account: select private.seed_demo_for('<user id>', current_date);
create function private.seed_demo_for(p_user uuid, p_today date)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_item jsonb;
begin
  for v_item in select value from jsonb_array_elements(private.demo_subscriptions(p_today)) loop
    perform private.write_subscription(p_user, gen_random_uuid(), v_item);
  end loop;
end;
$$;

-- resetDemo: replaces the caller's subscriptions (and read / dismissed state)
-- with the demo account. Returns the new subscriptions like get_subscriptions().
create function public.seed_demo_data(p_today date default null)
returns jsonb
language plpgsql
set search_path = ''
as $$
begin
  perform public.clear_my_data();
  perform private.seed_demo_for((select auth.uid()), coalesce(p_today, private.user_today()));
  return public.get_subscriptions();
end;
$$;

-- -----------------------------------------------------------------------------
-- Privileges
-- -----------------------------------------------------------------------------
revoke execute on function public.seed_demo_data(date) from public, anon;
grant execute on function public.seed_demo_data(date) to authenticated, service_role;

revoke execute on function
  private.demo_subscription_defs(),
  private.demo_subscriptions(date),
  private.seed_demo_for(uuid, date)
from public, anon, authenticated;
grant execute on function
  private.demo_subscription_defs(),
  private.demo_subscriptions(date),
  private.seed_demo_for(uuid, date)
to authenticated, service_role;
